def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    grid = []

    index = 2
    for _ in range(n):
        row = data[index].strip()
        grid.append(list(row))
        index += 1

    ans = n

    for bin in range(1 << n):
        exist = [False] * m
        cnt = 0
        for i in range(n):
            if (bin >> i) & 1:
                cnt += 1
                for j in range(m):
                    if grid[i][j] == "o":
                        exist[j] = True

        if all(exist):
            ans = min(ans, cnt)

    print(ans)
